do $$
declare item jsonb; q jsonb; opt text; module_uuid uuid; assessment_uuid uuid; question_uuid uuid; stage_no integer; q_no integer; opt_no integer; assessment_title text;
begin
 for item in select value from jsonb_array_elements($json$[[1,"Fundamentos da língua portuguesa",[["A placa com o desenho de um telefone e uma seta comunica por meio de:","Linguagem verbal","Linguagem não verbal","Linguagem escrita","Ausência de comunicação",1,"O desenho transmite uma orientação sem palavras; é linguagem não verbal."],["A língua é melhor definida como:","A realização individual da fala","Um sistema social de signos e regras compartilhado por uma comunidade","Apenas a escrita formal","Um conjunto aleatório de sons",1,"A língua é um sistema social de comunicação compartilhado por uma comunidade."],["Em uma conversa, a fala corresponde:","À realização individual e concreta da língua","Ao conjunto abstrato de regras","Somente à linguagem corporal","Exclusivamente à escrita",0,"A fala é o uso individual e concreto da língua em uma situação comunicativa."]]],[2,"Interpretação de textos",[["Uma informação explícita é aquela que:","Está diretamente apresentada no texto","Depende de adivinhação","Contradiz o texto","É sempre uma opinião",0,"A informação explícita aparece diretamente no texto."],["Em “João voltou a estudar”, pressupõe-se que:","João nunca estudou","João já estudava antes","João abandonou a escola para sempre","João não gosta de estudar",1,"A expressão “voltou a” pressupõe uma ação anterior que foi interrompida."],["Se Marcos pegou o guarda-chuva ao ver o céu escuro, pode-se inferir que:","Certamente ocorreu uma tempestade","Ele provavelmente se preparou para a possibilidade de chuva","Ele perdeu o ônibus","O céu estava limpo",1,"O contexto sugere precaução diante da possibilidade de chuva, sem provar que choveu."]]],[3,"Semântica e significação",[["Em “O banco da praça estava molhado”, banco significa:","Instituição financeira","Assento","Margem do rio","Conjunto de dados",1,"A expressão “da praça” indica o sentido de assento."],["“Descrição” e “discrição” são palavras:","Sinônimas","Antônimas","Parônimas","Idênticas em sentido",2,"São parônimas: têm forma semelhante, mas significados diferentes."],["A expressão “coração de pedra” apresenta sentido:","Literal","Conotativo","Científico","Denotativo obrigatório",1,"A expressão é figurada e sugere insensibilidade."]]],[4,"Organização textual",[["Uma receita culinária é predominantemente:","Narrativa","Injuntiva","Descritiva","Argumentativa",1,"A receita orienta o leitor a executar uma tarefa; predomina a injunção."],["Qual conectivo expressa concessão?","Portanto","Porque","Embora","Além disso",2,"“Embora” introduz uma ideia concessiva."],["Em “Ana chegou. Ela trouxe os livros”, o pronome ela contribui para:","Coesão referencial","Hipérbole","Rima","Ambiguidade obrigatória",0,"O pronome retoma Ana e conecta as frases."]]],[5,"Fonética e fonologia",[["A palavra “saúde” apresenta:","Ditongo","Hiato","Tritongo","Dígrafo",1,"As vogais a e ú ficam em sílabas diferentes: sa-ú-de."],["Em “chave”, CH representa:","Encontro consonantal","Dígrafo","Hiato","Tritongo",1,"Duas letras representam um único fonema: é um dígrafo."],["A palavra “médico” é:","Oxítona","Paroxítona","Proparoxítona","Monossílaba",2,"A sílaba tônica é a antepenúltima; portanto, é proparoxítona."]]],[6,"Ortografia e acentuação",[["Assinale a grafia correta:","Excessão","Exceção","Escessão","Ecessão",1,"A grafia correta é exceção."],["Qual palavra é proparoxítona?","Café","Fácil","Lâmpada","Também",2,"Lâmpada tem a antepenúltima sílaba tônica."],["Complete: “Não fui à aula _____ estava doente.”","Por que","Porque","Por quê","Porquê",1,"“Porque” junto e sem acento introduz uma explicação ou causa."]]],[7,"Classes gramaticais",[["Em “A menina inteligente respondeu”, inteligente é:","Substantivo","Verbo","Adjetivo","Advérbio",2,"Inteligente caracteriza o substantivo menina; portanto, é adjetivo."],["Em “O jantar estava pronto”, jantar é:","Verbo","Substantivo","Preposição","Conjunção",1,"A palavra nomeia um evento e está acompanhada de artigo."],["Qual classe modifica o verbo e pode indicar circunstância?","Artigo","Advérbio","Substantivo","Numeral",1,"O advérbio pode modificar o verbo e indicar tempo, lugar, modo e outras circunstâncias."]]],[8,"Morfologia e formação de palavras",[["Em “infeliz”, o elemento “in-” é:","Sufixo","Radical","Prefixo","Desinência",2,"O prefixo aparece antes do radical."],["“Passatempo” é formado por:","Composição por justaposição","Flexão","Derivação sufixal","Parassíntese",0,"Passatempo une dois radicais sem perda significativa de elementos."],["Em “felizmente”, “-mente” é:","Prefixo","Sufixo","Radical","Vogal temática",1,"O sufixo é acrescentado depois da base para formar o advérbio."]]],[9,"Sintaxe",[["Em “Os alunos resolveram a questão”, o sujeito é:","Resolveram","A questão","Os alunos","Questão",2,"Os alunos é o termo sobre o qual se declara algo."],["Em “Comprei um livro”, “um livro” exerce função de:","Objeto direto","Objeto indireto","Vocativo","Aposto",0,"Completa o verbo sem preposição obrigatória: objeto direto."],["O período “Estudei e revisei” apresenta:","Uma oração","Duas orações","Três orações","Nenhuma oração",1,"Há dois verbos e, portanto, duas orações."]]],[10,"Pontuação e crase",[["Qual frase isola corretamente o vocativo?","Maria venha aqui.","Maria, venha aqui.","Maria venha, aqui.","Maria venha aqui,",1,"O vocativo Maria deve ser separado por vírgula."],["Em “Fui à escola”, a crase resulta da fusão de:","Dois artigos","Preposição a + artigo a","Duas preposições","Pronome + verbo",1,"O verbo ir exige preposição a e escola admite artigo feminino a."],["Em “Começou a estudar”, a crase:","É obrigatória","Não ocorre antes de verbo","É sempre facultativa","Depende do sujeito",1,"Não se usa crase antes de verbo."]]],[11,"Figuras de linguagem e discursos",[["“Estou morrendo de fome” é exemplo de:","Eufemismo","Hipérbole","Metonímia","Antítese",1,"Hipérbole é o exagero intencional."],["“Seus olhos são estrelas” apresenta:","Metáfora","Comparação explícita","Ironia","Pleonasmo",0,"A metáfora aproxima elementos sem conectivo comparativo."],["“Que ótimo! Perdi o ônibus de novo”, dito com frustração, pode expressar:","Ironia","Eufemismo","Onomatopeia","Personificação",0,"O contexto indica sentido diferente do elogio literal."]]],[12,"Reescrita e concursos",[["A transformação da voz ativa para a passiva deve preservar:","A ideia principal","O sujeito agente na mesma função","O tempo futuro","A forma interrogativa",0,"A estrutura muda, mas a informação principal deve ser preservada."],["O conectivo “embora” expressa:","Causa","Consequência","Concessão","Conclusão",2,"“Embora” introduz uma relação concessiva."],["Ao resolver uma questão com o comando “assinale a alternativa incorreta”, deve-se:","Marcar a primeira opção verdadeira","Identificar a alternativa que não está correta","Ignorar o enunciado","Escolher a opção mais longa",1,"A palavra incorreta determina que se procure a alternativa errada."]]]]$json$::jsonb) loop
  stage_no := (item->>0)::integer;
  select id into module_uuid from public.modules where stage=stage_no and published=true order by created_at limit 1;
  if module_uuid is null then raise exception 'Módulo publicado não encontrado: %',stage_no; end if;
  assessment_title := 'Avaliação do módulo '||lpad(stage_no::text,2,'0')||' — '||(item->>1);
  select id into assessment_uuid from public.assessments where module_id=module_uuid and title=assessment_title limit 1;
  if assessment_uuid is null then
   insert into public.assessments(module_id,title,description,assessment_type,time_limit_seconds,published)
   values(module_uuid,assessment_title,'Avaliação de revisão com questões comentadas sobre os objetivos deste módulo.','module',900,true) returning id into assessment_uuid;
  end if;
  if not exists(select 1 from public.questions where assessment_id=assessment_uuid) then
   q_no:=0;
   for q in select value from jsonb_array_elements(item->2) loop
    q_no:=q_no+1;
    insert into public.questions(assessment_id,subject,prompt,context_text,difficulty,explanation,position,published)
    values(assessment_uuid,item->>1,q->>0,'Questão de revisão do módulo '||stage_no::text,2,q->>6,q_no,true) returning id into question_uuid;
    for opt_no in 1..4 loop
     opt:=q->>opt_no;
     insert into public.question_options(question_id,option_label,option_text,is_correct,explanation,position)
     values(question_uuid,chr(64+opt_no),opt,(opt_no-1)=(q->>5)::integer,q->>6,opt_no);
    end loop;
   end loop;
  end if;
 end loop;
end $$;